mapper.select:
SELECT pwd.main_id, pwd.basket_no, pwd.delivery_id, pd.id as pickDetailId, pd.sku_id, pd.sku_no, pd.picked_qty, pd.allocated_qty FROM wave_list_detail AS pwd inner join picking_lists AS pl on pl.source_id = pwd.delivery_id and pl.is_deleted = FALSE inner JOIN picking_detail AS pd ON pd.is_deleted = FALSE AND pd.main_id = pl.id
pwd.main_id = #{waveId}
and pwd.basket_no = #{basketNo}
and pd.sku_id = #{skuId}

select wl.id, wl.create_time, wl.update_time, wl.create_user_name, wl.update_user_name, wl.code, wl.name, wl.type, wl.status, wl.picking_cart_type, wl.picking_cart_code, wl.picking_type, wl.print_status, wl.picking_user_id, wl.picking_user_name, wl.picking_time, wl.print_time, wl.is_out_stock, wl.picking_print_status, wl.picking_print_time from wave_list wl where is_deleted = false
and ${params.sqlMap.default}
order by create_time desc
